using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "AbsorbAction", menuName = "Data/Battle/Battle Actions/Sentinel/AbsorbAction")]
public class AbsorbAction : ChooseDiceAction
{
	[Header("AbsorbAction")]
	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private ActionFace actionFace;

	public OmenLogic OmenLogic => omenLogic;

	public ActionFace ActionFace => actionFace;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		int count = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count;
		bool flag = false;
		if (diceOwnerEnum != 0)
		{
			if (count == 0)
			{
				flag = true;
			}
		}
		else if (playerHand)
		{
			if (count <= 1)
			{
				flag = true;
			}
		}
		else if (count == 0)
		{
			flag = true;
		}
		return !flag;
	}

	public override void Cast(GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
		for (int i = 0; i < diceList.Count; i++)
		{
			diceList[i].DestroyDiceDisposeAction();
		}
		omenLogic.ActivateOmen(actionFace.BattleAction, actionFace.ActionValue, null, null);
	}
}
